insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('9e7bc558-29a6-4af4-82d7-97d9567dc071', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$inleiding: resten van ontwormingsmiddelen in de poep van grote grazers$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context1.png$$,
   $$Jeroen Helmer (projectmedewerker van ARK Rewilding) en Jelmer Buijs (landbouwkundige) onderzochten de poep van paarden en koeien in natuurgebieden. Soms bevat de poep van deze grote grazers resten van de ontwormingsmiddelen die ze als medicijn toegediend kregen. Dit heeft nadelige gevolgen voor de biodiversiteit in het natuurgebied.$$, 'inline'),
  ('aef75064-cc00-4752-8fc1-9f0584dad377', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$kader: leven in de poep (afbeelding 1)$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context2.png$$,
   $$In de poep (afbeelding 1) leven behalve bacteriën na een tijdje ook veel larven van mestkevers en strontvliegen. Die eten halfverteerde organische resten die nog in de poep zitten. Deze insecten trekken andere organismen aan, zoals slakken en padden, die weer een prooi vormen voor egels, vogels en dassen.
afbeelding 1: tekening van koeienvlaaien met insecten, slakken, een pad, vogels en andere dieren$$, 'inline'),
  ('e9592be0-3ddc-429b-ac34-7811fedc5cfa', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$stikstofkringloop in het informatieboek$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context3.png$$,
   $$In je informatieboek staat de stikstofkringloop weergegeven.$$, 'inline'),
  ('79a01074-246e-49d7-9530-738974c75a6e', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$afbeelding 2: kringloop met gras en vakken S, T en U$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context4.png$$,
   $$Afbeelding 2 is een schematische weergave van een kringloop van stoffen waarbij bacteriën, gras, mestkevers en runderen betrokken zijn. Elke pijl stelt het transport van anorganische en/of organische stoffen voor. Drie vakken zijn met de letters S, T en U aangegeven.
afbeelding 2: kringloop met de vakken gras, S, T en U en genummerde pijlen: 1 van gras naar S, 2 van S naar T, 3 van T naar U, 4 van U naar gras, 5 van gras naar U, 6 van S naar U$$, 'inline'),
  ('66ace02e-905a-4d7b-b771-16bb44aeab1e', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$bacteriën, mestkevers en runderen invullen$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context5.png$$,
   $$In die vakken moeten bacteriën, mestkevers en runderen ingevuld worden.$$, 'inline'),
  ('91769fad-ae5b-4d8d-8e36-736e060d29b9', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$gangen van de gewone mestkever$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context6.png$$,
   $$De aanwezigheid van mestkevers in de mest is gunstig voor de groei van de vegetatie in het natuurgebied. De gewone mestkever (Geotrupes molestus) graaft in de bodem verticale tunnels van tientallen centimeters diep, met horizontale zijgangen. Aan het einde van elke zijgang wordt een eitje gelegd en daarna wordt de gang volgestopt met mest. Zaden die in de mest zitten worden zo verspreid. Op deze manier dragen de gangen van de gewone mestkever bij aan de groei van de vegetatie. De gangen van de gewone mestkever kunnen ook op andere manieren bijdragen aan de groei van planten.$$, 'inline'),
  ('1df137c6-cd9f-48d6-98d7-34663e5e9129', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$kader: nematoden maken darmvlokken kapot$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context7.png$$,
   $$Paarden en runderen die buiten lopen, krijgen vaak ontwormingsmiddelen toegediend omdat ze gemakkelijk geïnfecteerd raken met nematoden. Deze kleine wormpjes leven in hun darmkanaal en tasten de darmwand aan door darmvlokken kapot te maken. Geïnfecteerde veulens en kalveren kunnen daardoor een groeiachterstand oplopen.$$, 'inline'),
  ('df83f71b-0cc3-464f-bbcc-b8315b97b6d7', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$kader: mestonderzoek en ivermectine$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context8.png$$,
   $$Een infectie met nematoden is aan te tonen met mestonderzoek waarbij het aantal nematode-eitjes per gram mest wordt bepaald. Om de nematoden te bestrijden, geven veehouders ontwormingsmiddelen zoals ivermectine aan hun paarden en runderen. Ivermectine doodt echter niet alleen nematoden, maar ook insecten. Voor gewervelde dieren is het middel ongevaarlijk. Helmer en Buijs toonden aan dat in een aantal natuurgebieden ivermectine in de mest van paarden en runderen aanwezig is.$$, 'inline'),
  ('8f71732b-4cf1-4057-81b3-af987441e4de', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$ivermectine en de populatiegrootte van egels$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context9.png$$,
   $$Hoewel ivermectine ongevaarlijk is voor egels, kan de populatiegrootte van egels in een natuurgebied toch afnemen door dit ontwormingsmiddel in de mest.$$, 'inline'),
  ('198e8b5a-30bf-42d3-8134-97602008c8c8', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$kader: boerenwormkruid met thujon tegen nematoden$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context10.png$$,
   $$Helmer gaat in gesprek met veehouders die runderen en paarden laten grazen in natuurgebieden. Hij wijst erop dat in veel natuurgebieden ook boerenwormkruid groeit, een plant die de gifstof thujon bevat. Thujon zou helpen om nematoden in de darmen te bestrijden. Runderen en paarden eten vaak boerenwormkruid als ze last hebben van nematoden. In tegenstelling tot ivermectine is thujon biologisch snel afbreekbaar, en dus beter voor het behoud van de biodiversiteit in natuurgebieden.$$, 'inline'),
  ('e66fcc01-f921-4e82-82c9-a43376d9f447', '77c5d358-cb7c-4889-82af-4d551d1f993b', $$experiment met boerenwormkruid; beschikbare materialen$$,
   $$biologie-havo-2024-ii-poep-moet-leven-context11.png$$,
   $$Met een experiment kan onderzocht worden of grazen in een gebied met boerenwormkruid werkt tegen nematoden bij runderen. Voor dit experiment is het volgende beschikbaar:
− 20 runderen, geïnfecteerd met nematoden
− een natuurgebied waarin veel boerenwormkruid aanwezig is
− hekken en afzetdraad$$, 'inline'),
  ('57228a9d-abcf-488b-b16b-4fbb72123239', 'e83bb427-e284-4786-8285-5f66a30502a7', $$inleiding: atlete met het lange-QT-syndroom$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context1.png$$,
   $$De Amerikaanse atlete Michaela Gagne raakte als 17-jarige tijdens een wedstrijd hordenlopen buiten bewustzijn. Ze bleek het lange-QT- syndroom te hebben, een erfelijke hartritmestoornis. Haar leven nam toen een onverwachte wending.$$, 'inline'),
  ('2525d97c-a064-417a-9265-30238ce7d170', 'e83bb427-e284-4786-8285-5f66a30502a7', $$kader: LQTS en ecg's van een gezonde persoon en een persoon met LQTS (afbeelding 1)$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context2.png$$,
   $$Bij mensen met het lange-QT-syndroom (LQTS) is de impulsgeleiding van het hart verstoord. Dat is zichtbaar op een ecg (elektrocardiogram, afbeelding 1). Het QT-interval is bij hen langer dan normaal. Het hartritme kan daardoor bij inspanning ontregeld raken. De hartkamers kunnen dan abnormaal gaan samentrekken, wat kan leiden tot duizeligheid, bewusteloosheid of zelfs een acute hartstilstand.
afbeelding 1: twee ecg''s (tijd 0 tot 2,0 seconden) van een gezonde persoon en van een persoon met LQTS, met P, Q, R, S en T aangegeven; bij beide liggen de R-toppen bij ongeveer 0,35, 1,05 en 1,75 s; bij de persoon met LQTS is de T-golf breder en ligt hij verder van het QRS-complex$$, 'inline'),
  ('52aa676c-58fe-4b57-833a-4e4c6d734e60', 'e83bb427-e284-4786-8285-5f66a30502a7', $$drie uitspraken over de ecg's$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context3.png$$,
   $$Over de ecg’s in afbeelding 1 worden de volgende uitspraken gedaan:
1 Tijdens het QRS-complex trekken de boezems samen.
2 Bij de gezonde persoon is tijdens de top van de T-golf de aortaklep open.
3 De persoon met LQTS heeft een lagere hartslagfrequentie dan de gezonde persoon.$$, 'inline'),
  ('bd7b6a24-52d7-4da0-980d-343eba1c5f6f', 'e83bb427-e284-4786-8285-5f66a30502a7', $$slagvolume van 70 mL$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context4.png$$,
   $$Het slagvolume van het hart van de persoon met LQTS (afbeelding 1) is 70 mL.$$, 'inline'),
  ('532244c0-eb77-4e2b-8bee-8a0808aa3452', 'e83bb427-e284-4786-8285-5f66a30502a7', $$bètablokkers blokkeren receptoren op hartspiercellen$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context5.png$$,
   $$Sommige LQTS-patiënten krijgen bètablokkers als medicijn voorgeschreven. Bètablokkers blokkeren de werking van receptoren die zich op de hartspiercellen bevinden. Bepaalde hormonen kunnen daardoor geen stimulerend effect meer uitoefenen op de samentrekking van hartspiercellen.$$, 'inline'),
  ('41a5805f-cf3f-4d1b-9be9-1a08e0022e82', 'e83bb427-e284-4786-8285-5f66a30502a7', $$kader: ICD met elektrode in het hart (afbeelding 2 en 3)$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context6.png$$,
   $$Bij Gagne werd een ICD (implanteerbare cardioverter defibrillator, afbeelding 2) onder de huid geplaatst. Vanuit de ICD is een elektrode via een bloedvat tot onder in de punt van een hartkamer geschoven. Het apparaatje monitort de hartslag. Wanneer het hartritme verstoord raakt, geeft het uiteinde van de elektrode een schokje aan de hartwand. Zo kan het hartritme zich herstellen. Met een röntgenfoto (afbeelding 3) werd gecontroleerd of de elektrode juist was geplaatst.
afbeelding 2: foto van een ICD met elektrode
afbeelding 3: röntgenfoto van de borstkas met de ICD onder het sleutelbeen en de elektrode naar het hart$$, 'inline'),
  ('c3d540b4-51a3-449d-b0b7-33027d289435', 'e83bb427-e284-4786-8285-5f66a30502a7', $$röntgenfoto toont ader en hartkamer$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context7.png$$,
   $$Uit de röntgenfoto is af te leiden via welke ader de elektrode in het hart wordt gebracht en in welke hartkamer de elektrode zich bevindt.$$, 'inline'),
  ('0a6e56e3-e1f8-4054-8d5e-89c29633f9f2', 'e83bb427-e284-4786-8285-5f66a30502a7', $$kader: Miss Massachusetts met een litteken (afbeelding 4)$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context8.png$$,
   $$Omdat Gagne moest stoppen met atletiek, zocht ze een nieuwe uitdaging: ze schreef zich in voor de missverkiezing in haar staat. Ze won en werd de eerste Miss Massachusetts (afbeelding 4) met een zichtbaar litteken onder haar sleutelbeen. Het litteken valt op doordat het bindweefsel waaruit het litteken bestaat, een iets lichtere kleur heeft dan haar huid.
afbeelding 4: portretfoto van Michaela Gagne met kroon$$, 'inline'),
  ('bc1f1eb4-e259-4e6f-99d3-9c334695a323', 'e83bb427-e284-4786-8285-5f66a30502a7', $$afbeelding 5: huid met een litteken$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context9.png$$,
   $$Afbeelding 5 is een schematische tekening van de huid met een litteken.
afbeelding 5: tekening van opperhuid en lederhuid; links normale huid met onderaan de opperhuid donkere, vertakte cellen, rechts een litteken met onregelmatig bindweefsel zonder die donkere cellen$$, 'inline'),
  ('4ec2d870-f6ae-460a-81fb-042680ac9370', 'e83bb427-e284-4786-8285-5f66a30502a7', $$AED en een groepje cellen dat impulsen opwekt (afbeelding 6)$$,
   $$biologie-havo-2024-ii-een-miss-met-een-litteken-context10.png$$,
   $$Na haar verkiezing zette Gagne zich in om op scholen AED''s te laten plaatsen. Een AED (automatische externe defibrillator, afbeelding 6) kan levensreddend zijn bij een hartstilstand. Het apparaat geeft een elektrische schok, waardoor het hart wordt gereset. Daarna gaat het hart weer regelmatig kloppen doordat een groepje cellen van het hart regelmatig impulsen opwekt.
afbeelding 6: foto van een AED in een kastje aan de muur$$, 'inline'),
  ('0e15222e-5309-4f65-a552-ce83280917e1', 'ab227497-b369-464f-b843-f8943e1bdc27', $$inleiding: Mare raakt geïnteresseerd in gifkikkers$$,
   $$biologie-havo-2024-ii-gifkikkers-context1.png$$,
   $$Na het zien van een documentaire over het Amazonewoud, raakt Mare geïnteresseerd in gifkikkers. Ze zoekt naar informatie over deze dieren en over de mogelijkheid om zelf gifkikkers te houden.$$, 'inline'),
  ('0fa3818a-6804-4d20-9dca-9798216d3995', 'ab227497-b369-464f-b843-f8943e1bdc27', $$kader: website over een terrarium voor driekleurige gifkikkers$$,
   $$biologie-havo-2024-ii-gifkikkers-context2.png$$,
   $$Mare denkt erover om een terrarium in te richten voor driekleurige gifkikkers (Epipedobates tricolor).
Op een website leest ze:
De ideale temperatuur overdag voor de driekleurige gifkikker is 23 °C, in ieder geval tussen de 20 en 25 °C. ''s Nachts mag de temperatuur niet lager worden dan 15 °C. De luchtvochtigheid is minimaal 80 procent. Het terrarium richt je in met klimplanten en bromelia''s, en op de bodem maak je voldoende schuilplaatsen. Je voert de gifkikkers met fruitvliegjes en keverlarven.
foto van een driekleurige gifkikker$$, 'inline'),
  ('99d01a63-d6e6-42fd-86e4-93b6de13be29', 'ab227497-b369-464f-b843-f8943e1bdc27', $$drie uitspraken over driekleurige gifkikkers$$,
   $$biologie-havo-2024-ii-gifkikkers-context3.png$$,
   $$Over de driekleurige gifkikkers worden de volgende uitspraken gedaan:
1 De optimumtemperatuur is 25 °C.
2 De habitat wordt bepaald door de biotische en abiotische factoren.
3 Luchtvochtigheid en temperatuur zijn abiotische factoren.$$, 'inline'),
  ('5b8a529b-1229-4560-a17c-e0554e4d54d3', 'ab227497-b369-464f-b843-f8943e1bdc27', $$kader: epibatidine in de huid via prooien$$,
   $$biologie-havo-2024-ii-gifkikkers-context4.png$$,
   $$In hun natuurlijke leefomgeving in Peru eten driekleurige gifkikkers geleedpotige dieren zoals mieren, termieten, kevers en mijten. De huid van de driekleurige gifkikker bevat epibatidine, een gifstof die dodelijk is voor bijna alle predatoren. Epibatidine wordt geproduceerd door giftige planten. Driekleurige gifkikkers verkrijgen epibatidine via prooien die van deze giftige planten eten.$$, 'inline'),
  ('893b3179-727d-497f-887d-c66e9d153809', 'ab227497-b369-464f-b843-f8943e1bdc27', $$kader: epibatidine bindt aan acetylcholinereceptoren$$,
   $$biologie-havo-2024-ii-gifkikkers-context5.png$$,
   $$Epibatidine bindt aan receptoren voor de neurotransmitter acetylcholine en remt zo de impulsoverdracht in synapsen. Hierdoor heeft de stof een verlammend effect bij predatoren van de driekleurige gifkikker. Epibatidine bindt op hetzelfde deel van de receptor als acetylcholine.$$, 'inline'),
  ('f598e8b0-2ab0-4e30-b4a4-f96d42df88e0', 'ab227497-b369-464f-b843-f8943e1bdc27', $$drie uitspraken over acetylcholine en epibatidine$$,
   $$biologie-havo-2024-ii-gifkikkers-context6.png$$,
   $$Over de overeenkomsten tussen acetylcholine en epibatidine worden de volgende uitspraken gedaan:
1 De moleculen hebben een overeenkomst in ruimtelijke structuur.
2 De moleculen zijn beide neurotransmitters.
3 De moleculen zijn beide organische verbindingen.$$, 'inline'),
  ('60198689-36d7-48b1-b556-fc12e14ecbed', 'ab227497-b369-464f-b843-f8943e1bdc27', $$puntmutatie in de acetylcholinereceptor; aminozuurvolgorde van twee soorten$$,
   $$biologie-havo-2024-ii-gifkikkers-context7.png$$,
   $$De driekleurige gifkikker is ongevoelig voor epibatidine. Dit komt doordat de acetylcholine-receptor van de driekleurige gifkikker een beetje anders is dan die van zijn predatoren. Dat is het gevolg van een puntmutatie in het gen dat codeert voor de acetylcholine-receptor. Door de mutatie bindt epibatidine minder sterk aan deze acetylcholine-receptor. Door een aantal andere mutaties is de sterkte van de binding van acetylcholine aan de receptor onveranderd.
Onderzoekers vergeleken het gen voor de acetylcholine-receptor van de driekleurige gifkikker (Epipedobates tricolor) met dat van de gifkikkersoort Allobates zaparo, die wél gevoelig is voor epibatidine. Hieronder is de aminozuurvolgorde van een deel van de receptor van beide soorten gifkikkers weergegeven.
positie aminozuur: 107 | 108 | 109 | 110
Allobates zaparo: Tyr - Cys - Asn - Ala
Epipedobates tricolor: Tyr - Ser - Asn - Ala$$, 'inline'),
  ('01040513-71e8-405e-9489-82136d9c2c20', 'ab227497-b369-464f-b843-f8943e1bdc27', $$ander aminozuur op plaats 108$$,
   $$biologie-havo-2024-ii-gifkikkers-context8.png$$,
   $$In de receptor van E. tricolor is dus op plaats 108 een ander aminozuur ingebouwd.$$, 'inline'),
  ('6cab553c-a355-450d-9d8b-6d6c7c071a19', 'ab227497-b369-464f-b843-f8943e1bdc27', $$Mare beweert dat haar gifkikkers niet giftig zullen zijn$$,
   $$biologie-havo-2024-ii-gifkikkers-context9.png$$,
   $$De ouders van Mare vinden haar plan voor een terrarium geen goed idee. Ze zijn bang dat de gifkikkers giftig zullen zijn. Mare beweert dat de driekleurige gifkikkers in haar terrarium niet giftig zullen zijn.$$, 'inline'),
  ('145eeb95-2e6c-4848-a9b7-f0b7c2bb6682', '6cffd313-bab0-4863-bb01-01bba37888ba', $$inleiding: honden sporen de gele-drakenziekte op$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-context1.png$$,
   $$De Amerikaanse plantenziektekundige Tim Gottwald traint honden om de gele-drakenziekte in een vroeg stadium op te sporen bij citrusbomen.$$, 'inline'),
  ('36f8a5ed-324a-42d8-a104-02d21a1702a7', '6cffd313-bab0-4863-bb01-01bba37888ba', $$kader: Liberibacter asiaticus verspreid door bladvlooien (afbeelding 1)$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-context2.png$$,
   $$De gele-drakenziekte wordt veroorzaakt door de bacterie Liberibacter asiaticus. Deze bacterie wordt verspreid via bladvlooien (afbeelding 1) die plantensap opzuigen uit de bastvaten van citrus-soorten. De ziekte kan hele sinaasappel- en citroenplantages verwoesten.
afbeelding 1: tekening van een bladvlo met schaalbalk van 1 mm$$, 'inline'),
  ('b0e144b5-3e13-4d67-bab6-5865eb80a6da', '6cffd313-bab0-4863-bb01-01bba37888ba', $$monocultuur via ongeslachtelijke voortplanting$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-context3.png$$,
   $$Een citrusplantage bestaat meestal uit een monocultuur van citrusbomen die via ongeslachtelijke voortplanting verkregen zijn.$$, 'inline'),
  ('7ddb317b-ead6-4c71-b8c4-8ad5ed1bd267', '6cffd313-bab0-4863-bb01-01bba37888ba', $$PLCP-enzymen en SDE1 in en rond een bastvat (afbeelding 2)$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-context4.png$$,
   $$Als een bladvlo met de bacterie is besmet en hij zijn snuit in een blad van een citrusboom prikt, komen de bacteriën in een bastvat terecht. Citrusbomen zijn tegen verschillende ziekteverwekkers beschermd doordat de cellen die zich naast de bastvaten bevinden, eiwit-splitsende enzymen (PLCP-enzymen) produceren. Deze enzymen verhinderen dat ziekteverwekkers zich kunnen vermenigvuldigen. De bacterie L. asiaticus geeft echter een bepaald eiwit (SDE1) af, dat de werking van PLCP-enzymen blokkeert.
In afbeelding 2 zijn met nummers drie eiwitten aangegeven die aanwezig zijn in cellen in en rondom een bastvat dat geïnfecteerd is met de bacterie L. asiaticus. Deze eiwitten zijn:
− geïnactiveerd PLCP-enzym
− SDE1
− werkzaam PLCP-enzym
afbeelding 2: schematische tekening van een bastvat met een bacterie en een naastgelegen cel; 1 wijst een los gebogen eiwit aan, 2 een driehoekje en 3 een gebogen eiwit waaraan een driehoekje vastzit; pijlen geven transport tussen bastvat en cel aan$$, 'inline'),
  ('fcf4ea7c-1267-4613-9104-910784136d8e', '6cffd313-bab0-4863-bb01-01bba37888ba', $$vergeling van bladeren; vruchten blijven klein$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-context5.png$$,
   $$De bladeren van een citrusboom worden enkele maanden na de infectie geel, waardoor de vruchten niet afrijpen, klein blijven en vroegtijdig van de boom vallen.$$, 'inline'),
  ('b4a5f8dc-969b-4007-b679-6f12b6d88696', '6cffd313-bab0-4863-bb01-01bba37888ba', $$DNA-analyse van een bladmonster$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-context6.png$$,
   $$Omdat de vergeling van de bladeren niet direct optreedt, kan pas na enkele maanden met het blote oog worden waargenomen dat de boom geïnfecteerd is. Met DNA-analyse van een bladmonster kan de infectie in een eerder stadium aangetoond worden.$$, 'inline'),
  ('94a1849c-5cd2-48e6-a17c-a2ee80b133e8', '6cffd313-bab0-4863-bb01-01bba37888ba', $$kader: experiment met vier speurhonden (afbeelding 3) en tabel met fouten$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-context7.png$$,
   $$Door een infectie met Liberibacter asiaticus verandert de geur van een citrusboom. Mensen kunnen de geurverandering niet waarnemen, maar honden wel. Gottwald trainde vier honden om de geur van geïnfecteerde bomen te herkennen. Hij leerde ze om naast de bomen met die geur te gaan zitten (afbeelding 3).
afbeelding 3: foto van een man met een hond tussen citrusbomen in potten op een veld
Gottwald bepaalde vervolgens met een experiment hoe geschikt de honden waren voor hun taak. Als test liep hij met een hond over een veld met 100 citrusbomen in potten, waarvan sommige bomen waren geïnfecteerd. Gottwald noteerde of de hond een geïnfecteerde boom niet herkende (een vals negatief resultaat) of ging zitten bij een boom die niet geïnfecteerd was (een vals positief resultaat). Elke hond deed de test tien keer. De 100 potten werden na elke test op een andere plaats gezet. De resultaten staan in de onderstaande tabel.
tabel aantal fouten (hond | vals negatief | vals positief)
Akim | 1 | 3
Boby | 4 | 0
Foreszt | 0 | 9
Vera | 4 | 5$$, 'inline'),
  ('dd8ad07a-a968-47f8-af1d-afcedab8f092', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$inleiding: chronisch ontstoken lever door hepatitis C$$,
   $$biologie-havo-2024-ii-levertransplantatie-context1.png$$,
   $$Jan heeft een infectie met het hepatitis C-virus gehad, waardoor zijn lever chronisch ontstoken is. Dit heeft geleid tot de vorming van littekenweefsel. Omdat zijn leverfunctie sterk is afgenomen, komt hij in aanmerking voor een levertransplantatie.$$, 'inline'),
  ('655cac77-00e1-4fe7-a937-4ed4bcfcbe1f', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$kader: hepatitis C is een RNA-virus$$,
   $$biologie-havo-2024-ii-levertransplantatie-context2.png$$,
   $$Het hepatitis C-virus is een RNA-virus dat hoofdzakelijk wordt overgedragen via bloed-bloedcontact.$$, 'inline'),
  ('3454e0b2-fd9b-4414-bab4-a13f22bf4ba2', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$bloedonderzoek naar antistoffen tegen hepatitis C$$,
   $$biologie-havo-2024-ii-levertransplantatie-context3.png$$,
   $$De chronische hepatitis C-infectie werd bij Jan aangetoond met behulp van bloedonderzoek. Bij dit bloedonderzoek werd gezocht naar antistoffen tegen hepatitis C.$$, 'inline'),
  ('ed158841-bffd-4940-92aa-7e4baa0771dd', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$kader: levercirrose$$,
   $$biologie-havo-2024-ii-levertransplantatie-context4.png$$,
   $$Door de chronische ontsteking van Jans lever zijn veel levercellen beschadigd geraakt en vervolgens afgestorven. Op deze plaatsen is littekenweefsel ontstaan. Door de vorming van littekenweefsel sterven ook steeds meer niet-geïnfecteerde cellen. Deze toestand van de lever wordt levercirrose genoemd. Omdat de leverfunctie bij Jan hierdoor te veel is afgenomen, is een levertransplantatie nodig.$$, 'inline'),
  ('dadd746a-e9f6-4bda-b2cc-e369a5a03667', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$kader: het medicijn Sofosbuvir$$,
   $$biologie-havo-2024-ii-levertransplantatie-context5.png$$,
   $$Voordat Jan een nieuwe lever krijgt, is het belangrijk dat hij helemaal genezen is van hepatitis C. Hij krijgt daarom een behandeling met het medicijn Sofosbuvir. Dit medicijn bevat nucleotiden die op uracil lijken. Als die nucleotiden worden ingebouwd tijdens de vorming van RNA, kan er geen nieuw nucleotide meer aan worden gekoppeld. Het RNA kan dan dus niet langer worden. Jan neemt Sofosbuvir als pil in.$$, 'inline'),
  ('d6cbb559-024c-49db-ae18-df4ef4fe4df1', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$drie uitspraken over Sofosbuvir$$,
   $$biologie-havo-2024-ii-levertransplantatie-context6.png$$,
   $$Over de behandeling met Sofosbuvir worden de volgende uitspraken gedaan:
1 Door Sofosbuvir worden er minder eiwitten geproduceerd.
2 Door Sofosbuvir wordt de vorming van erfelijk materiaal voor nieuwe hepatitis C-virussen verhinderd.
3 De nucleotiden uit Sofosbuvir moeten eerst worden verteerd om te kunnen worden opgenomen.$$, 'inline'),
  ('d51c773d-f4e5-4d17-b9ce-b8cc7859be7a', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$kader: kwaliteit van een donorlever verbeteren met spoelvloeistof$$,
   $$biologie-havo-2024-ii-levertransplantatie-context7.png$$,
   $$Er is een donorlever voor Jan beschikbaar gekomen, maar deze is niet in goede staat. Vincent de Meyer, transplantatiearts van het Universitair Medisch Centrum Groningen, heeft een methode om de kwaliteit van een slechte donorlever te verbeteren. Eerst koppelt hij de bloedvaten van de lever aan een machine en plaatst hij de lever in een bak met een koude (4 tot 12 °C), zuurstofrijke spoelvloeistof. Via de bloedvaten wordt deze vloeistof door de lever gepompt. Na een uur wordt de vloeistof langzaam opgewarmd tot 37 °C. Ondertussen wordt de werking van de lever regelmatig gecontroleerd. De afbraak van melkzuur in de lever wordt gecontroleerd door de pH te meten van de spoelvloeistof die uit de lever stroomt. Ook wordt gemeten hoeveel gal de lever produceert.$$, 'inline'),
  ('95156d33-4096-4433-824e-134a45907920', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$zuurstof zet een celorganel aan het werk$$,
   $$biologie-havo-2024-ii-levertransplantatie-context8.png$$,
   $$De zuurstof in de spoelvloeistof is bedoeld om een bepaald celorganel in de levercellen aan het werk te zetten. Dit celorganel produceert dan een energierijke stof die nodig is om de celprocessen in andere delen van de cel te laten verlopen.$$, 'inline'),
  ('89513235-0e5b-4607-8819-8a0192299a25', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$celprocessen verlopen sneller door opwarmen$$,
   $$biologie-havo-2024-ii-levertransplantatie-context9.png$$,
   $$Door het opwarmen verlopen de celprocessen in de lever steeds sneller.$$, 'inline'),
  ('19e147ac-83dc-4317-b99b-0c5477b8012a', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$gal en de spijsvertering$$,
   $$biologie-havo-2024-ii-levertransplantatie-context10.png$$,
   $$Gal heeft een belangrijke functie bij de spijsvertering.$$, 'inline'),
  ('35d9042b-abe1-43ab-b8f0-13b0334d625c', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$kader: zoon Marco als levende donor$$,
   $$biologie-havo-2024-ii-levertransplantatie-context11.png$$,
   $$Helaas lukt het De Meyer niet om de kwaliteit van de donorlever voldoende te verbeteren. Daarom besluit hij deze lever niet te transplanteren. Het is echter ook mogelijk om een deel van de lever van een levende donor te transplanteren. Jans zoon Marco wil graag donor zijn voor zijn vader. Maar dan moeten Jan en Marco wel dezelfde bloedgroep hebben.$$, 'inline'),
  ('dcac4bd2-fa12-49ca-b442-226a9c9d857c', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$AB0-bloedgroepen van Jan en de moeder van Marco$$,
   $$biologie-havo-2024-ii-levertransplantatie-context12.png$$,
   $$Het AB0-bloedgroepensysteem heeft de autosomale allelen Iᴬ, Iᴮ en i. Bij bloedgroep 0 hoort het genotype ii.
Vader Jan heeft bloedgroep AB. Het genotype van de moeder van Marco is Iᴮi. Marco''s bloedgroep is nog niet bekend.$$, 'inline'),
  ('a7aa2706-692d-464f-a835-6bafb72ddb65', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$kader: Marco heeft bloedgroep AB; leverbiopt$$,
   $$biologie-havo-2024-ii-levertransplantatie-context13.png$$,
   $$Uit bloedonderzoek blijkt dat Marco’s bloedgroep ook AB is. Om te controleren of de lever van Marco gezond is, wordt een leverbiopt genomen: met een naald wordt wat leverweefsel afgenomen voor onderzoek.$$, 'inline'),
  ('c234530d-955a-4007-9d62-3027dff70329', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$maximaal uitademen tijdens de biopsie$$,
   $$biologie-havo-2024-ii-levertransplantatie-context14.png$$,
   $$Tijdens de biopsie moet Marco maximaal uitademen.$$, 'inline'),
  ('31fe9d03-e748-4aa5-8fcf-7eb6ad6422b9', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$kader: de transplantatie$$,
   $$biologie-havo-2024-ii-levertransplantatie-context15.png$$,
   $$Marco’s lever blijkt gezond en twee weken later vindt de transplantatie plaats. De lever van Jan wordt verwijderd en gelijktijdig wordt twee derde deel van Marco’s lever verwijderd. Dit gedeelte wordt in het lichaam van Jan aangesloten op de galbuis en de bloedvaten van de lever. In twee tot drie maanden groeien de levers van Marco en Jan weer uit tot een normale grootte.$$, 'inline'),
  ('d74ea2b8-cb43-4c26-bae1-419a1d3e30d1', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$afbeelding van de lever met bloedvaten P, Q en R$$,
   $$biologie-havo-2024-ii-levertransplantatie-context16.png$$,
   $$In de afbeelding van de lever zijn drie bloedvaten met letters aangegeven.
afbeelding: tekening van de lever met galblaas; P is een bloedvat aan de bovenkant van de lever dat uitkomt in een groot bloedvat, Q en R zijn bloedvaten aan de onderkant; ook de leverslagader is aangegeven$$, 'inline'),
  ('a6e6dfc0-7922-4267-a5b5-d52ec7fee34f', 'daff15dd-041a-4d1f-81dd-c734786dde7c', $$levenslang medicijnen na transplantatie$$,
   $$biologie-havo-2024-ii-levertransplantatie-context17.png$$,
   $$Jan moet vanwege de transplantatie de rest van zijn leven bepaalde medicijnen blijven slikken.$$, 'inline'),
  ('21e14557-db07-422e-b19d-7d35eca09593', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$inleiding: zeebaarzen nemen af door overbevissing$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context1.png$$,
   $$Het gaat niet goed met de zeebaars. Door overbevissing en verlies van habitat neemt hun aantal steeds verder af. Door het instellen van vangstbeperkingen en het kweken van zeebaars wordt geprobeerd om herstel van de wilde populaties mogelijk te maken.$$, 'inline'),
  ('f860447b-a1c6-4589-b62e-1e81b3e2e5cd', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$kader: Europese zeebaars (afbeelding 1)$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context2.png$$,
   $$De Europese zeebaars (Dicentrarchus labrax, afbeelding 1) is een geliefde consumptievis. De soort komt voor in de zeeën en oceanen rond Europa. Jonge zeebaarzen eten vooral dierlijk plankton, kreeftjes en kleine garnalen. Volwassen dieren voeden zich met kreeftachtigen, wormen, weekdieren en visjes. Zeebaarzen vormen een prooi voor dolfijnen en bruinvissen.
De Europese zeebaars wordt gemiddeld 50 cm groot. Vrouwtjes worden geslachtsrijp vanaf een grootte van 31 tot 40 cm; mannetjes vanaf 23 tot 30 cm. De voortplanting vindt plaats in diepere delen van de zee.
afbeelding 1: tekening van een zeebaars$$, 'inline'),
  ('022060a6-36bd-4a1c-b474-f582d2b305a7', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$een ecosysteem bestaat uit consumenten, producenten en reducenten$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context3.png$$,
   $$Een ecosysteem bestaat uit consumenten, producenten en reducenten.$$, 'inline'),
  ('82c26674-ffc6-47e0-8c9a-6c20edd3bd39', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$twee groepen Europese zeebaarzen$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context4.png$$,
   $$Er blijken twee groepen Europese zeebaarzen te bestaan. Een daarvan leeft in het koude water van het noordoostelijke deel van de Atlantische Oceaan, de andere in het warmere water in het westelijke deel van de Middellandse Zee. Tussen deze groepen vindt nauwelijks uitwisseling van individuen plaats.$$, 'inline'),
  ('2181071f-230d-4db6-817f-fb5d0510eb50', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$vangstbeperkingen met een minimumlengte van 42 cm$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context5.png$$,
   $$De Europese Unie stelt jaarlijks vangstbeperkingen voor zeebaars vast. Zo mogen sportvissers van april tot en met december per dag per visser maximaal twee zeebaarzen meenemen, met een minimumlengte van 42 cm.$$, 'inline'),
  ('a05a156a-46f9-4788-84d9-74d8e57d4912', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$kader: kweken van zeebaars in drijvende kooien (afbeelding 2)$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context6.png$$,
   $$Een van de oplossingen om overbevissing tegen te gaan, is het kweken van vis. Op verschillende plaatsen in de Middellandse Zee wordt zeebaars gekweekt in grote kooien die in het zeewater drijven (afbeelding 2). De vissen worden gevoerd met brokjes gemaakt van vismeel en visolie.
afbeelding 2: foto van ronde viskweekkooien die in zee drijven$$, 'inline'),
  ('73f0cdf7-eb66-420f-9295-d2015bf573b7', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$niet-gegeten voer veroorzaakt eutrofiëring$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context7.png$$,
   $$Het voer dat niet gegeten wordt door de vissen in de kooi, komt terecht op de zeebodem en kan eutrofiëring veroorzaken van de omringende zee. Dit is echter niet de belangrijkste oorzaak van de eutrofiëring door viskweek.$$, 'inline'),
  ('8cffd3d4-ffa5-477e-81a5-19922f4af463', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$plantaardig voer in plaats van vismeel en visolie$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context8.png$$,
   $$Het vismeel en de visolie in het voer zijn vaak afkomstig van wilde vis. Wetenschappers onderzoeken of zeebaars ook gevoerd kan worden met plantaardig voer. Het blijkt dat het aandeel visolie in het voer kan worden vervangen door plantaardige olie zonder dat de groei en smaak van de zeebaars worden beïnvloed.$$, 'inline'),
  ('b9562ac0-2bff-4df9-8ba5-988be0a955e3', 'e1c61a1c-10c4-457b-9ce7-f680ba57b8d9', $$antibiotica in kwekerijen$$,
   $$biologie-havo-2024-ii-vissen-op-zeebaars-context9.png$$,
   $$Om een bacteriële infectieziekte binnen een kwekerij tegen te gaan, worden antibiotica toegediend. Hiermee moet voorzichtig worden omgegaan, omdat daardoor problemen voor de volksgezondheid kunnen ontstaan. Het veelvuldig toedienen van antibiotica aan kweekvis kan ertoe leiden dat infecties bij de mens niet met een antibioticum kunnen worden behandeld.$$, 'inline'),
  ('f9f7a1b1-ef5f-472b-92cf-201475f1fc5e', '7f850c34-ff90-4670-8139-69c742faa3b7', $$inleiding: verpleegkundige in het Gamma Knife Centrum$$,
   $$biologie-havo-2024-ii-gamma-knife-context1.png$$,
   $$Jana is verpleegkundige in het Gamma Knife Centrum van het Elisabeth- TweeSteden Ziekenhuis in Tilburg. Ze begeleidt patiënten die behandeld worden met een Gamma Knife-bestralingstoestel.$$, 'inline'),
  ('5424d717-55e6-4546-9ec3-f14df1e2f1d6', '7f850c34-ff90-4670-8139-69c742faa3b7', $$kader: brughoektumor uit schwanncellen van de gehoor- en evenwichtszenuw$$,
   $$biologie-havo-2024-ii-gamma-knife-context2.png$$,
   $$Een van de patiënten die Jana begeleidt, heeft een brughoektumor. Dit is een goedaardig gezwel dat is ontstaan uit de schwanncellen van de gehoor- en evenwichtszenuw, die loopt vanuit het binnenoor met een hoek naar de hersenstam. Als gevolg van de tumor ging hij steeds slechter horen met zijn linkeroor.$$, 'inline'),
  ('b66f3fcb-a019-4f18-ad59-9db17936bb7f', '7f850c34-ff90-4670-8139-69c742faa3b7', $$myelineschedes en impulsgeleiding$$,
   $$biologie-havo-2024-ii-gamma-knife-context3.png$$,
   $$Schwanncellen vormen myeline-schedes rondom de uitlopers van zenuwcellen. Myeline-schedes hebben een belangrijke functie bij de impulsgeleiding.$$, 'inline'),
  ('f7834e82-5546-498d-9a54-65594d951336', '7f850c34-ff90-4670-8139-69c742faa3b7', $$uitspraak over slechter horen door beschadiging$$,
   $$biologie-havo-2024-ii-gamma-knife-context4.png$$,
   $$Over hoe de beschadiging van de gehoor- en evenwichtszenuw leidt tot slechter horen, wordt de volgende uitspraak gedaan: Door de beschadiging kunnen de impulsen vanaf de zintuigcellen niet meer goed via de ...(1)... zenuwcellen en de hersenstam naar de …(2)… worden geleid.$$, 'inline'),
  ('65eaa9f7-e2e0-49f1-b9a4-a95582c63151', '7f850c34-ff90-4670-8139-69c742faa3b7', $$kader: erfelijke mutatie in het NF2-gen$$,
   $$biologie-havo-2024-ii-gamma-knife-context5.png$$,
   $$Een brughoektumor kan ontstaan door een erfelijke mutatie in het NF2- gen. De mutatie leidt tot fouten in de aanmaak van merline-eiwit. Dit eiwit remt normaal de celdeling. Door de mutatie is dit eiwit afwezig of niet functioneel. Het mutante NF2-allel erft autosomaal dominant over.$$, 'inline'),
  ('1cbfcba2-f25a-4388-9c40-60262b0a5f35', '7f850c34-ff90-4670-8139-69c742faa3b7', $$twee uitspraken over de mutatie van het NF2-gen$$,
   $$biologie-havo-2024-ii-gamma-knife-context6.png$$,
   $$Over de mutatie van het NF2-gen worden de volgende uitspraken gedaan:
1 De mutatie is alleen aanwezig in zenuwcellen.
2 Door de mutatie wordt celdeling geremd.$$, 'inline'),
  ('477411ff-cc08-4a55-8854-fa768b2fc460', '7f850c34-ff90-4670-8139-69c742faa3b7', $$kader: tumor kan de hersenstam beschadigen$$,
   $$biologie-havo-2024-ii-gamma-knife-context7.png$$,
   $$De neurochirurg van het ziekenhuis legt uit dat een brughoektumor een goedaardig gezwel is, maar dat het toch moet worden verwijderd omdat het kan doorgroeien en dan de hersenstam kan beschadigen.$$, 'inline'),
  ('a7fb7db9-3392-4c4d-82d5-2af0f9ddb4f8', '7f850c34-ff90-4670-8139-69c742faa3b7', $$klassieke operatie en Gamma Knife-behandeling (afbeelding 1)$$,
   $$biologie-havo-2024-ii-gamma-knife-context8.png$$,
   $$Er zijn twee mogelijke behandelingen van een brughoektumor. Bij een klassieke operatie wordt een opening in de schedel gemaakt en wordt de tumor operatief verwijderd. Bij een behandeling met de Gamma Knife wordt een tumor zeer nauwkeurig bestraald. Het stralingsapparaat heeft 192 radioactieve bronnen die rondom het hoofd zijn geplaatst en gamma-straling richten op één punt (afbeelding 1). Daar waar de straling samenkomt, wordt het weefsel vernietigd. Zo wordt alleen de tumor ''weggesneden''.
afbeelding 1: schematische tekening van een hoofd met daaromheen radioactieve bronnen waarvan de gamma-straling samenkomt in de tumor
De twee behandelingen worden vergeleken op drie mogelijke voordelen:$$, 'inline'),
  ('840c19c0-2ff2-4531-968a-fc5b32cfa837', '7f850c34-ff90-4670-8139-69c742faa3b7', $$drie mogelijke voordelen$$,
   $$biologie-havo-2024-ii-gamma-knife-context9.png$$,
   $$1 Er is geen risico op een bacteriële infectie van buitenaf.
2 Er kan behandeld worden op plaatsen in het hoofd die anders moeilijk te bereiken zijn.
3 Het tumorweefsel kan onderzocht worden op andere mutaties.$$, 'inline'),
  ('f735514b-9667-4e5e-9a65-49ec5818ae2f', '7f850c34-ff90-4670-8139-69c742faa3b7', $$oedeem na de behandeling; drie processen$$,
   $$biologie-havo-2024-ii-gamma-knife-context10.png$$,
   $$Enkele dagen na de behandeling kan de patiënt last krijgen van duizeligheid. Jana kan de patiënt dan geruststellen: de duizeligheid wordt meestal veroorzaakt door oedeemvorming. Oedeem is een tijdelijke ophoping van weefselvloeistof en is ontstaan door weefselschade. Bij de regeling van de hoeveelheid weefselvloeistof zijn de volgende processen betrokken:
1 afvoer van vocht via de lymfevaten
2 filtratie van vocht uit de bloedvaten
3 resorptie van vocht naar de bloedvaten$$, 'inline');

