   $$biologie-havo-2024-ii-poep-moet-leven-vraag6.png$$, $$1p 6 Verklaar dat het aantal egels afneemt door de aanwezigheid van ivermectine in de mest.$$, array['aef75064-cc00-4752-8fc1-9f0584dad377', 'df83f71b-0cc3-464f-bbcc-b8315b97b6d7', '8f71732b-4cf1-4057-81b3-af987441e4de']::uuid[]),
