   $$biologie-havo-2024-ii-een-miss-met-een-litteken-vraag10.png$$, $$1p 10 Noteer de naam van zo’n hormoon.$$, array['532244c0-eb77-4e2b-8bee-8a0808aa3452']::uuid[]),
