   $$biologie-havo-2024-ii-gifkikkers-vraag15.png$$, $$1p 15 Noteer de naam van het proces waarbij de concentratie gifstof in een driekleurige gifkikker toeneemt.$$, array['5b8a529b-1229-4560-a17c-e0554e4d54d3']::uuid[]),
