   $$biologie-havo-2024-ii-gifkikkers-vraag16.png$$, $$2p 16 Beschrijf hoe door evolutionaire processen de giftigheid van de driekleurige gifkikker is ontstaan.$$, array['5b8a529b-1229-4560-a17c-e0554e4d54d3', '60198689-36d7-48b1-b556-fc12e14ecbed']::uuid[]),
