   $$biologie-havo-2024-ii-gifkikkers-vraag19.png$$, $$1p 19 Geef een argument dat Mares bewering ondersteunt.$$, array['0fa3818a-6804-4d20-9dca-9798216d3995', '5b8a529b-1229-4560-a17c-e0554e4d54d3', '6cab553c-a355-450d-9d8b-6d6c7c071a19']::uuid[]),
