   '["ongeslachtelijke voortplanting", "genetische variatie", "monocultuur", "klonen", "vatbaarheid voor ziekte"]'::jsonb,
   $$Uitleggen dat genetisch identieke bomen allemaal even vatbaar zijn, zodat een ziekte zich door de hele plantage kan verspreiden.$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-vraag20.png$$, $$2p 20 Leg uit dat door deze manier van voortplanting een plantage kwetsbaar is voor infectieziekten.$$, array['145eeb95-2e6c-4848-a9b7-f0b7c2bb6682', '36f8a5ed-324a-42d8-a104-02d21a1702a7', 'b0e144b5-3e13-4d67-bab6-5865eb80a6da']::uuid[]),
