   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-vraag21.png$$, $$1p 21 Schrijf de nummers 1, 2 en 3 onder elkaar en noteer erachter welk eiwit met het betreffende nummer in afbeelding 2 is aangegeven.$$, array['7ddb317b-ead6-4c71-b8c4-8ad5ed1bd267']::uuid[]),
