   '[{"domain": "Zelfregulatie", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["fotosynthese", "bladgroen", "assimilatie", "glucose", "transport via bastvaten"]'::jsonb,
   $$Uitleggen dat gele bladeren minder bladgroen hebben, zodat minder fotosynthese plaatsvindt en minder suikers naar de vruchten gaan.$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-vraag22.png$$, $$2p 22 Leg uit waardoor de vruchten klein blijven als de bladeren geel worden.$$, array['fcf4ea7c-1267-4613-9104-910784136d8e']::uuid[]),
  ('ac9e5e68-9466-4918-ac66-06f630a68c4f', '6cffd313-bab0-4863-bb01-01bba37888ba', 23,
   '[{"domain": "Evolutie", "subdomain": "Selectie"}]'::jsonb,
   '["DNA-analyse", "bacterieel DNA", "ziekteverwekker aantonen", "DNA als drager van erfelijke informatie"]'::jsonb,
   $$Verklaren dat het DNA van de bacterie verschilt van dat van de boom en zo in een bladmonster kan worden aangetoond.$$,
   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-vraag23.png$$, $$1p 23 Verklaar dat met DNA-analyse aangetoond kan worden dat een boom geïnfecteerd is.$$, array['36f8a5ed-324a-42d8-a104-02d21a1702a7', 'b4a5f8dc-969b-4007-b679-6f12b6d88696']::uuid[]),
