   $$biologie-havo-2024-ii-hond-speurt-naar-zieke-boom-vraag24.png$$, $$1p 24 Verklaar waarom de potten na elke test op een andere plaats gezet werden.$$, array['94a1849c-5cd2-48e6-a17c-a2ee80b133e8']::uuid[]),
